mapper.update:
UPDATE SCHED_EXTERNAL_API_EXEC_LOG
   SET FINISHED_AT = #{finishedAt},
       RUN_MILLIS = #{runMillis},
       STATUS = #{status},
       ERROR_MESSAGE = #{errorMessage}
 WHERE EXECUTION_ID = #{executionId}

mapper.select:
WITH CALL_SUMMARY AS ( SELECT EXECUTION_ID, COUNT(DISTINCT REQUEST_SEQUENCE) AS REQUEST_COUNT, COUNT(*) AS ATTEMPT_COUNT, COUNT(*) - COUNT(DISTINCT REQUEST_SEQUENCE) AS RETRY_COUNT, COALESCE(SUM(RUN_MILLIS), 0) AS API_RUN_MILLIS FROM SCHED_EXTERNAL_API_CALL_LOG GROUP BY EXECUTION_ID ) SELECT E.EXECUTION_ID, E.EXTERNAL_API_ID, A.API_NAME, E.FIRE_INSTANCE_ID, E.STATUS, E.ERROR_MESSAGE, COALESCE(C.REQUEST_COUNT, 0) AS REQUEST_COUNT, COALESCE(C.ATTEMPT_COUNT, 0) AS ATTEMPT_COUNT, COALESCE(C.RETRY_COUNT, 0) AS RETRY_COUNT, E.RUN_MILLIS AS TOTAL_RUN_MILLIS, COALESCE(C.API_RUN_MILLIS, 0) AS API_RUN_MILLIS, E.STARTED_AT, E.FINISHED_AT FROM SCHED_EXTERNAL_API_EXEC_LOG E LEFT JOIN SCHED_EXTERNAL_API A ON E.EXTERNAL_API_ID = A.EXTERNAL_API_ID LEFT JOIN CALL_SUMMARY C ON E.EXECUTION_ID = C.EXECUTION_ID WHERE 1 = 1
AND A.API_NAME LIKE '%' || #{apiName} || '%'
AND E.STATUS = #{status}
AND E.STARTED_AT >= #{startDate}
AND E.STARTED_AT < #{endDateExclusive}
ORDER BY E.STARTED_AT DESC OFFSET #{offset} ROWS FETCH NEXT #{size} ROWS ONLY

SELECT COUNT(*)
FROM SCHED_EXTERNAL_API_EXEC_LOG E
LEFT JOIN SCHED_EXTERNAL_API A
  ON E.EXTERNAL_API_ID = A.EXTERNAL_API_ID
WHERE 1 = 1

	AND A.API_NAME LIKE '%' || #{apiName} || '%'


	AND E.STATUS = #{status}


	AND E.STARTED_AT  >=  #{startDate}


	AND E.STARTED_AT  <  #{endDateExclusive}
